// Generated by /ship test coverage audit.
// Value: protects=every info-page CTA and section link resolves to a real view or existing page, and every page appears in a footer group;
//   fails_when=a slug is renamed/removed or a CTA typo silently falls back to Home or "Page not found";
//   why_new=e2e clicks only the vendors CTA; seam=none
import { describe, expect, it } from 'vitest';
import { PAGES, PAGE_GROUPS } from './pages';
import { parseRoute } from './routes';
import { CATEGORIES, CITIES, findCategory, findCity } from './discovery';

const targets = Object.values(PAGES).flatMap((p) => [
  ...(p.cta ? [{ from: p.slug, to: p.cta.to }] : []),
  ...p.sections.flatMap((s) => (s.link ? [{ from: p.slug, to: s.link.to }] : [])),
]);

describe('info page content', () => {
  it('keys match slugs and every group is shown in the footer', () => {
    const groups = new Set(PAGE_GROUPS.map((g) => g.group));
    for (const [key, def] of Object.entries(PAGES)) {
      expect(def.slug).toBe(key);
      expect(groups.has(def.group)).toBe(true);
    }
  });

  it.each(targets)('$from links to a real destination ($to)', ({ to }) => {
    if (/^(mailto:|tel:|https?:)/.test(to)) return;
    const parsed = parseRoute(to);
    if (parsed.kind === 'view') expect(to.replace(/^#?\/?/, '')).toBe(parsed.view); // not a silent fallback to Home
    else if (parsed.kind === 'page') expect(PAGES[parsed.slug]).toBeDefined();
    else if (parsed.kind === 'near') expect(findCategory(parsed.slug)).toBeDefined();
    else expect(findCity(parsed.slug)).toBeDefined();
  });

  it('discovery slugs are unique and round-trip through the router', () => {
    for (const list of [CATEGORIES, CITIES]) {
      const slugs = list.map((x) => x.slug);
      expect(new Set(slugs).size).toBe(slugs.length);
    }
    for (const c of CITIES) expect(parseRoute(`city/${c.slug}`)).toEqual({ kind: 'city', slug: c.slug });
  });

  it('rider copy makes no earnings promise (plan: rider pay is Phase 3 and not yet set)', () => {
    const r = PAGES.riders;
    const text = [r.title, r.lede, ...r.sections.flatMap((x) => [x.heading, x.body ?? '', ...(x.bullets ?? [])]), r.apply!.body].join(' ');
    expect(text).not.toMatch(/₦\s?\d|per week|\/ ?week|average/i);
    expect(r.status).toBe('planned');
  });
});
